if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$identifier=trim((string)($_POST['identifier']??''));$password=(string)($_POST['password']??'');$q=$pdo->prepare("SELECT u.id,u.username,u.email,u.password_hash,u.active,r.name role FROM users u JOIN roles r ON r.id=u.role_id WHERE (u.username=:i OR u.email=:i) LIMIT 1");$q->execute(['i'=>$identifier]);$u=$q->fetch();if($u&&(int)$u['active']===1&&password_verify($password,$u['password_hash'])){session_regenerate_id(true);$_SESSION['auth_user']=['id'=>(int)$u['id'],'username'=>$u['username'],'email'=>$u['email'],'role'=>$u['role']];$pdo->prepare("UPDATE users SET last_login_at=NOW() WHERE id=?")->execute([$u['id']]);$pdo->prepare("INSERT INTO audit_logs(user_id,action,module,ip_address) VALUES(?,?,?,?)")->execute([$u['id'],'LOGIN','AUTH',$_SERVER['REMOTE_ADDR']??null]);redirect('/dashboard.php');}$error='Invalid login details or inactive account.';}
